<?php
function acField(string $name,string $label,array $values,array $options=[],string $type='text',bool $required=true):void{
 $value=$values[$name]??'';echo '<label>'.e($label);if($options){echo '<select name="'.e($name).'" '.($required?'required':'').'>';echo '<option value="">'.($required?'Select…':'All').'</option>';foreach($options as $k=>$v){$key=array_is_list($options)?$v:$k;echo '<option value="'.e($key).'" '.((string)$value===(string)$key?'selected':'').'>'.e($v).'</option>';}echo '</select>';}else echo '<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.($required?'required':'').' '.($type==='number'?'min="0.01" max="2000" step="0.01"':'').'>';echo '</label>';
}
function acHidden(array $r,string $action):void{csrf();echo '<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.(int)$r['id'].'"><input type="hidden" name="revision" value="'.(int)$r['revision'].'">';}
function acConfigForm(array $r=[],array $post=[]):void{
 if(($r['kind']??$post['kind']??$_GET['kind']??'attendance')==='reassessment'){
  global $user;$originals=all("SELECT id,module_code,module_name,programme,academic_year,semester FROM academic_records WHERE kind='assessment' AND status='Submitted'".(acAdmin($user)?'':' AND owner_id=?').' ORDER BY id DESC',acAdmin($user)?[]:[$user['id']]);$windows=all('SELECT * FROM academic_reassessment_windows WHERE enabled=1 AND opens_at<=? AND closes_at>=? ORDER BY id DESC',[now(),now()]);$options=[];foreach($originals as $o)$options[(string)$o['id']]='#'.$o['id'].' · '.$o['module_code'].' · '.$o['programme'].' · '.$o['academic_year'];$win=[];foreach($windows as $w)$win[(string)$w['id']]=$w['title'].' · '.$w['academic_year'].' · Semester '.$w['semester'];$v=array_merge($r['metadata']??[],$post);
  if(!$windows){echo '<p class="notice">Re-assessment entry is not open. Exam Cell/Admin must announce entry dates.</p>';return;}
  if(!$originals){echo '<p class="notice">Submit the original module assessment first.</p>';return;}
  echo '<form method="post">';if($r)acHidden($r,'ac_save_metadata');else{csrf();echo '<input type="hidden" name="action" value="ac_create">';}echo '<input type="hidden" name="kind" value="reassessment"><div class="form-grid">';acField('original_id','Original submitted module',$v,$options);acField('window_id','Open re-assessment entry window',$v,$win);echo '</div><p class="notice">Enter only the new ESE raw mark. Original CA is retained. Passing requires 40% in CA, 40% in ESE, and a total of 50. A successful re-assessment is capped at 50. Three or more failed modules require repeating the semester; an incomplete cohort is not automatically eligible.</p><button>Create / save re-assessment draft</button></form>';return;
 }
 $meta=$r['metadata']??[];$v=array_merge(['kind'=>$_GET['kind']??'attendance','section'=>'A','semester'=>'I','study_year'=>'I','academic_year'=>date('Y').'-'.((int)date('Y')+1),'has_exam'=>'No'],$r,$meta,$post);if(is_bool($v['has_exam']))$v['has_exam']=$v['has_exam']?'Yes':'No';$components=$v['components']??[['name'=>'Class test','type'=>'CA','max'=>100,'weight'=>20],['name'=>'Presentation','type'=>'CA','max'=>50,'weight'=>20],['name'=>'Project','type'=>'CA','max'=>30,'weight'=>20],['name'=>'End Semester Examination','type'=>'ESE','max'=>100,'weight'=>40]];if(is_string($components)){try{$components=acDecode($components);}catch(Throwable $e){$components=[];}}if(!isset($meta['has_exam'])&&!isset($post['has_exam']))$v['has_exam']='Yes';
 ?><form method="post" class="ac-config" data-programmes="<?=e(acJson(examProgrammeMap()))?>" data-components="<?=e(acJson($components))?>"><?php if($r)acHidden($r,'ac_save_metadata');else{csrf();echo '<input type="hidden" name="action" value="ac_create">';}?><input type="hidden" name="kind" value="<?=e($v['kind'])?>"><div class="form-grid">
 <?php acField('department','Department',$v,departments());acField('programme','Programme',$v,examProgrammes());acField('academic_year','Academic year (e.g. 2026-2027)',$v);acField('classroom','Classroom',$v);acField('study_year','Year',$v,['I','II','III','IV']);acField('semester','Semester',$v,['I','II']);acField('section','Section',$v);acField('module_code','Module code',$v);acField('module_name','Module name',$v);acField('contact_hours','DPD contact hours',$v,[],'number');?></div>
 <p class="notice">Contact hours must exactly match the DPD / module descriptor. Credits (normally 12) do not determine contact hours.</p>
 <?php if($v['kind']!=='attendance'):?><h3>Assessment structure</h3><p>Enter raw maximum marks and contribution to the final 100%. There can be several CA components and only one ESE component.</p><?php acField('has_exam','Semester exam?',$v,['Yes','No']);?><div class="table-wrap"><table class="ac-components"><thead><tr><th>Component name</th><th>Type</th><th>Maximum marks</th><th>Weight (%)</th><th></th></tr></thead><tbody></tbody></table></div><input type="hidden" name="components" value="<?=e(acJson($components))?>"><div class="ac-toolbar"><button type="button" class="secondary ac-add-component">+ CA component</button><strong class="ac-weight" aria-live="polite"></strong></div><noscript>Enable JavaScript to configure assessment components.</noscript><?php endif;?>
 <?php if($v['kind']==='reassessment'):?><div class="notice">This is a separate attempt for PL/DAA review. It does not replace original marks, determine pass/fail, or apply a mark cap.</div><div class="form-grid"><?php acField('original_id','Original assessment receipt number',$v);acField('attempt','Attempt label (e.g. October 2026)',$v);?></div><?php endif;?>
 <button><?= $r?'Save module details':'Create private draft →'?></button></form><?php
